style.css:
@-moz-document domain("discord.com") {
/* Fondo general */
    body {
        background: url("https://i.imgur.com/0fYxZ4R.png") no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* Colores principales estilo HUD */
    .theme-dark {
        --background-primary: #0d1f0d !important; /* Verde oscuro */
        --background-secondary: #1a331a !important;
        --background-tertiary: #264d26 !important;
        --text-normal: #c6ffb3 !important; /* Verde claro */
        --text-muted: #7fbf7f !important;
        --brand-experiment: #55ff55 !important; /* Verde brillante */
    }

    /* Bordes pixelados */
    .container-1NXEtd, .chat-2ZfjoI, .members-3WRCEx {
        border: 2px solid #55ff55 !important;
        border-radius: 0px !important; /* Estilo cuadrado */
        image-rendering: pixelated !important;
    }

    /* Íconos estilo pixel */
    .icon-2xnN2Y {
        filter: hue-rotate(90deg) saturate(150%) !important;
    }

    /* Barra superior como barra de vida */
    .title-29uC1r {
        background: linear-gradient(to right, #ff5555 50%, #333 50%) !important;
        color: #fff !important;
        font-family: "Press Start 2P", monospace !important;
        text-transform: uppercase !important;
    }
}
